use std :: path :: PathBuf ; use clap :: { Parser , Subcommand , ValueEnum } ; use forge_domain :: { AgentId , ConversationId , Effort , ModelId , ProviderId } ; use clap :: Parser ; use pretty_assertions :: assert_eq ; use super :: * ; use std :: path :: PathBuf ; impl Cli { # [doc = " Determines whether the CLI should start in interactive mode."] # [doc = ""] # [doc = " Returns true when no prompt, piped input, or subcommand is provided,"] # [doc = " indicating the user wants to enter interactive mode."] pub fn is_interactive (& self) -> bool { self . prompt . is_none () && self . piped_input . is_none () && self . subcommands . is_none () } }